import{_ as l,a0 as p,w as o,s as d,I as a,x as n,a1 as e,A as i,ao as r}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const D=JSON.parse('{"title":"開放文檔格式 ODT 文件格式解析 | LCTT x X-CMD","titleTemplate":false,"description":"開放文檔格式 ODT 文件格式解析 | LCTT (202311) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"開放文檔格式 ODT 文件格式解析 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"開放文檔格式 ODT 文件格式解析 | LCTT (202311) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202311/20220815 How ODT files are structured","title":"開放文檔格式 ODT 文件格式解析","tag":"202311","desc":""},"relativePath":"202311/20220815 How ODT files are structured.md","filePath":"[post].md"}'),u={name:"202311/20220815 How ODT files are structured.md"};function m(g,s,f,b,h,c){const t=p("Link");return o(),d("div",null,[s[24]||(s[24]=a("h1",{id:"開放文檔格式-odt-文件格式解析",tabindex:"-1"},[n("開放文檔格式 ODT 文件格式解析 "),a("a",{class:"header-anchor",href:"#開放文檔格式-odt-文件格式解析","aria-label":"Permalink to “開放文檔格式 ODT 文件格式解析”"},"​")],-1)),s[25]||(s[25]=a("p",null,[a("img",{src:"https://img.linux.net.cn/data/attachment/album/202311/01/223607j3nvjcuw5jcocbz3.jpg",alt:""})],-1)),s[26]||(s[26]=a("blockquote",null,[a("p",null,"開放文檔格式（ODF）基於開放標準，你可以使用其它工具檢查它們，甚至從中提取數據。你只需要知道從哪裏開始。")],-1)),s[27]||(s[27]=a("p",null,"過去，文字處理文件是封閉的專有格式。在一些較舊的文字處理軟件中，文檔文件本質上是該軟件的內存轉儲。雖然這樣可以讓加載文件更快，但也使文檔文件格式變得不透明。",-1)),a("p",null,[s[1]||(s[1]=n("2005 年左右，",-1)),s[2]||(s[2]=a("ruby",null,[n("結構化信息標準促進組織"),a("rt",null," Organization for the Advancement of Structured Information Standards")],-1)),s[3]||(s[3]=n("（OASIS）為所有類型的辦公文檔定義了一種開放格式，即",-1)),s[4]||(s[4]=a("ruby",null,[n("辦公應用程序開放文檔格式"),a("rt",null,"Open Document Format for Office Applications")],-1)),s[5]||(s[5]=n("（ODF）。由於 ODF 是基於 ",-1)),e(t,{href:"http://OpenOffice.org"},{default:i(()=>[...s[0]||(s[0]=[n("OpenOffice.org",-1)])]),_:1}),s[6]||(s[6]=n(" 的 XML 文件規範的開放式標準，因此你也可以將其簡稱為 “開放文檔格式”。ODF 包括幾種文件類型，包括用於 ",-1)),s[7]||(s[7]=a("ruby",null,[n("開放文檔文本"),a("rt",null,"OpenDocument Text")],-1)),s[8]||(s[8]=n(" 文檔的 ODT。ODT 文件中有很多值得探索的內容，它的本質是一個 Zip 文件。",-1))]),s[28]||(s[28]=r(`<h3 id="odt-文件結構" tabindex="-1">ODT 文件結構 <a class="header-anchor" href="#odt-文件結構" aria-label="Permalink to “ODT 文件結構”">​</a></h3><p>跟所有 ODF 文件一樣，ODT 文件實際上是一個 XML 文檔和其它文件的 Zip 壓縮包。使用 Zip 可以佔用更少的磁盤空間，同時也意味着可以用標準 Zip 工具來檢查它。</p><p>我有一篇關於 IT 領導力的文章，名為“Nibbled to death by ducks”，我將其保存為 ODT 文件。由於 ODF 文件是一個 zip 容器，你可以用 <code>unzip</code> 命令來檢查它：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ unzip -l &#39;Nibbled to death by ducks.odt&#39;</span></span>
<span class="line"><span>Archive: Nibbled to death by ducks.odt</span></span>
<span class="line"><span>Length Date Time Name</span></span>
<span class="line"><span>39 07-15-2022 22:18 mimetype</span></span>
<span class="line"><span>12713 07-15-2022 22:18 Thumbnails/thumbnail.png</span></span>
<span class="line"><span>915001 07-15-2022 22:18 Pictures/10000201000004500000026DBF6636B0B9352031.png</span></span>
<span class="line"><span>10879 07-15-2022 22:18 content.xml</span></span>
<span class="line"><span>20048 07-15-2022 22:18 styles.xml</span></span>
<span class="line"><span>9576 07-15-2022 22:18 settings.xml</span></span>
<span class="line"><span>757 07-15-2022 22:18 meta.xml</span></span>
<span class="line"><span>260 07-15-2022 22:18 manifest.rdf</span></span>
<span class="line"><span>0 07-15-2022 22:18 Configurations2/accelerator/</span></span>
<span class="line"><span>0 07-15-2022 22:18 Configurations2/toolpanel/</span></span>
<span class="line"><span>0 07-15-2022 22:18 Configurations2/statusbar/</span></span>
<span class="line"><span>0 07-15-2022 22:18 Configurations2/progressbar/</span></span>
<span class="line"><span>0 07-15-2022 22:18 Configurations2/toolbar/</span></span>
<span class="line"><span>0 07-15-2022 22:18 Configurations2/popupmenu/</span></span>
<span class="line"><span>0 07-15-2022 22:18 Configurations2/floater/</span></span>
<span class="line"><span>0 07-15-2022 22:18 Configurations2/menubar/</span></span>
<span class="line"><span>1192 07-15-2022 22:18 META-INF/manifest.xml</span></span>
<span class="line"><span>970465 17 files</span></span></code></pre></div><p>我想強調 Zip 文件結構的以下幾個元素：</p><ol><li><p><code>mimetype</code> 文件用於定義 ODF 文檔。處理 ODT 文件的程序，如文字處理程序，可以使用該文件來驗證文檔的 MIME 類型。對於 ODT 文件，它應該總是：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>application/vnd.oasis.opendocument.text</span></span></code></pre></div></li><li><p><code>META-INF</code> 目錄中有一個 <code>manifest.xml</code> 文件。它包含查找 ODT 文件其它組件的所有信息。任何讀取 ODT 文件的程序都從這個文件開始定位其它內容。例如，我的 ODT 文檔的 <code>manifest.xml</code> 文件包含這一行，它定義了在哪裏可以找到主要內容:</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>&lt;manifest:file-entry manifest:full-path=&quot;content.xml&quot; manifest:media-type=&quot;text/xml&quot;/&gt;</span></span></code></pre></div></li><li><p><code>content.xml</code> 文件包含文檔的實際內容。</p></li><li><p>我的文檔中只有一張截圖，它位於 <code>Pictures</code> 目錄中。</p></li></ol><h3 id="從-odt-中提取文件" tabindex="-1">從 ODT 中提取文件 <a class="header-anchor" href="#從-odt-中提取文件" aria-label="Permalink to “從 ODT 中提取文件”">​</a></h3><p>由於 ODT 文檔是一個具有特定結構的 Zip 文件，因此可以從中提取文件。你可以先解壓縮整個 ODT 文件，例如使用 <code>unzip</code> 命令：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ unzip -q &#39;Nibbled to death by ducks.odt&#39; -d Nibbled</span></span></code></pre></div><p>一位同事最近向我要了一份我在文章中提到的圖片。通過查看 <code>META-INF/manifest.xml</code> 文件，我找到了嵌入圖像的確切位置。用 <code>grep</code> 命令可以找到描述圖像的行:</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ cd Nibbled</span></span>
<span class="line"><span>$ grep image META-INF/manifest.xml</span></span>
<span class="line"><span>&lt;manifest:file-entry manifest:full-path=&quot;Thumbnails/thumbnail.png&quot; manifest:media-type=&quot;image/png&quot;/&gt;</span></span>
<span class="line"><span>&lt;manifest:file-entry manifest:full-path=&quot;Pictures/10000201000004500000026DBF6636B0B9352031.png&quot; manifest:media-type=&quot; image/png”/&gt;</span></span></code></pre></div><p>我要找的圖像保存在 <code>Pictures</code> 文件夾中。可以通過列出目錄的內容來驗證：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ ls -F</span></span>
<span class="line"><span>Configurations2/ manifest.rdf meta.xml Pictures/ styles.xml</span></span>
<span class="line"><span>content.xml META-INF/ mimetype settings.xml Thumbnails/</span></span></code></pre></div><p>就是這張圖片：</p><p><img src="https://opensource.com/sites/default/files/2022-07/ducks.png" alt="Image of rubber ducks in two bowls"></p><h3 id="開放文檔格式" tabindex="-1">開放文檔格式 <a class="header-anchor" href="#開放文檔格式" aria-label="Permalink to “開放文檔格式”">​</a></h3><p>ODF 是一種開放的文件格式，它可以描述文字處理文件（ODT）、電子表格文件（ODS）、演示文稿（ODP）和其它文件類型。由於 ODF 格式基於開放標準，因此可以使用其他工具檢查它們，甚至從中提取數據。你只需要知道從哪裏開始。所有 ODF 文件都以 <code>META-INF/manifest.xml</code> 為“引導”文件，通過它你能找到其餘的所有內容。</p><p><em>（題圖：MJ/d245ab34-f0b0-452c-b29a-ece9aa78f11a）</em></p><hr>`,19)),a("p",null,[s[10]||(s[10]=n("via: ",-1)),e(t,{href:"https://opensource.com/article/22/8/odt-files"},{default:i(()=>[...s[9]||(s[9]=[n("https://opensource.com/article/22/8/odt-files",-1)])]),_:1})]),a("p",null,[s[15]||(s[15]=n("作者：",-1)),e(t,{href:"https://opensource.com/users/jim-hall"},{default:i(()=>[...s[11]||(s[11]=[n("Jim Hall",-1)])]),_:1}),s[16]||(s[16]=n(" 選題：",-1)),e(t,{href:"https://github.com/lkxed"},{default:i(()=>[...s[12]||(s[12]=[n("lkxed",-1)])]),_:1}),s[17]||(s[17]=n(" 譯者：",-1)),e(t,{href:"https://github.com/toknow-gh"},{default:i(()=>[...s[13]||(s[13]=[n("toknow-gh",-1)])]),_:1}),s[18]||(s[18]=n(" 校對：",-1)),e(t,{href:"https://github.com/%E6%A0%A1%E5%B0%8D%E8%80%85ID"},{default:i(()=>[...s[14]||(s[14]=[n("校對者ID",-1)])]),_:1})]),a("p",null,[s[21]||(s[21]=n("本文由 ",-1)),e(t,{href:"https://github.com/LCTT/TranslateProject"},{default:i(()=>[...s[19]||(s[19]=[n("LCTT",-1)])]),_:1}),s[22]||(s[22]=n(" 原創編譯，",-1)),e(t,{href:"https://linux.cn/"},{default:i(()=>[...s[20]||(s[20]=[n("Linux中國",-1)])]),_:1}),s[23]||(s[23]=n(" 榮譽推出",-1))])])}const O=l(u,[["render",m]]);export{D as __pageData,O as default};
